sksl:
uniform shader image;
uniform shader blurred;
uniform float2 size;
uniform float time;
uniform float blur;
uniform float mask;
half4 main(float2 coord) {
    half4 c = image.eval(coord);
    if (blur <= 0.0) return c;
    half4 b = blurred.eval(coord);
    float e = clamp(1.2 / max(blur, 1.0), 0.01, 0.5);
    float a = smoothstep(0.5 - e, 0.5 + e, float(b.a));
    if (mask > 0.5) a = min(a, float(c.a));
    float3 rgb = c.a > 0.004 ? float3(c.rgb) / float(c.a) : b.a > 0.004 ? float3(b.rgb) / float(b.a) : float3(0.0);
    return half4(half3(rgb * a), half(a));
}
